head.script:
scwin.anchor1_onclick = function() {
    var idx = input1.getValue();
    return false;
    var selectedIdx = dsTest.getMatchedIndex("testIdx", idx, true)[0];
    alert(selectedIdx);
    if (selectedIdx >= 0) {
        grdTest.setFocusedCell(selectedIdx, 0);
    } else {
        alert("존재하지 않는 열 번호입니다.");
    }
};
scwin.anchor2_onclick = function() {
    return false;
    var currentFilter = dsTest.getFilterList(); //현재 필터링 상태 저장
    console.log(currentFilter);
    dsTest.clearFilter(); //필터링 해제
    for (var fIdx = 0; fIdx < currentFilter.length; fIdx++) {
        console.log(currentFilter[fIdx]);
        var options = {
            type: currentFilter[fIdx].type,
            colIndex: currentFilter[fIdx].colIndex,
            key: currentFilter[fIdx].key,
            condition: currentFilter[fIdx].condition,
            exactMatch: currentFilter[fIdx].exactMatch
        };
        dsTest.setColumnFilter(options);
    }
};
scwin.dsTest_onbeforecolumnfilterchange = function() {
    localStorage.setItem("log1", "dsTest_onbeforecolumnfilterchange");
    console.log("dsTest_onbeforecolumnfilterchange: ");
};
scwin.dsTest_onaftercolumnfilterchange = function() {
    localStorage.setItem("log2", "dsTest_onaftercolumnfilterchange");
    console.log("dsTest_onaftercolumnfilterchange: ");
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grdTest_column4_filter').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grdTest_customFilter_list').children[0].children[1].click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grdTest_item_0_selectbox_column4').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grdTest_item_0_selectbox_column4_itemTable_1').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grdTest_item_1_selectbox').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grdTest_item_1_selectbox_itemTable_1').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grdTest_btnConform_column4').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == 'dsTest_onbeforecolumnfilterchange'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log2') == 'dsTest_onaftercolumnfilterchange'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log1");
    localStorage.removeItem("log2");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
